CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, name text NOT NULL, email_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orgs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, status text NOT NULL DEFAULT 'active', legal_name text, business_number text, representative_name text, business_address text, business_type text, business_item text, tax_invoice_email text, seat_athletes int NOT NULL DEFAULT 100, seat_coaches int NOT NULL DEFAULT 10, seat_guardians_per_athlete int NOT NULL DEFAULT 2, seat_org_admins int NOT NULL DEFAULT 3, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('org_admin','coach','guardian','athlete')), athlete_id uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,user_id,role));
CREATE TABLE platform_staff(user_id uuid PRIMARY KEY REFERENCES users ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, active_membership_id uuid REFERENCES memberships ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), idle_expires_at timestamptz NOT NULL, absolute_expires_at timestamptz NOT NULL, user_agent text, ip inet);
CREATE TABLE login_attempts(id bigserial PRIMARY KEY, scope text NOT NULL CHECK(scope IN ('ip','email')), key_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX login_attempts_window ON login_attempts(scope,key_hash,created_at DESC);
CREATE INDEX sessions_user ON sessions(user_id,absolute_expires_at);
CREATE INDEX memberships_user ON memberships(user_id);
CREATE TABLE teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, name text NOT NULL, sport text NOT NULL CHECK(sport='baseball'), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,name));
CREATE TABLE athletes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, team_id uuid NOT NULL REFERENCES teams, display_name text NOT NULL, birth_date date NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','erasure_pending','erased')), position text, grade_label text, bats text, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE memberships ADD CONSTRAINT memberships_athlete_fk FOREIGN KEY(athlete_id) REFERENCES athletes ON DELETE CASCADE;
CREATE TABLE invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('org_admin','coach','guardian','athlete')), email text NOT NULL, athlete_id uuid REFERENCES athletes ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX athletes_org_status ON athletes(org_id,status);
CREATE TABLE coach_assignments(org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, coach_user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, athlete_id uuid NOT NULL REFERENCES athletes ON DELETE CASCADE, PRIMARY KEY(org_id,coach_user_id,athlete_id));
CREATE INDEX coach_assignments_coach ON coach_assignments(coach_user_id,org_id);
CREATE TABLE guardian_links(org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, guardian_user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, athlete_id uuid NOT NULL REFERENCES athletes ON DELETE CASCADE, relation text, PRIMARY KEY(org_id,guardian_user_id,athlete_id));
CREATE TABLE athlete_profiles(org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, athlete_id uuid PRIMARY KEY REFERENCES athletes ON DELETE CASCADE, profile_visibility text NOT NULL DEFAULT 'private' CHECK(profile_visibility IN ('private','team')), training_visibility text NOT NULL DEFAULT 'private' CHECK(training_visibility IN ('private','team')), games_visibility text NOT NULL DEFAULT 'private' CHECK(games_visibility IN ('private','team')), goals_visibility text NOT NULL DEFAULT 'private' CHECK(goals_visibility IN ('private','team')));
CREATE TABLE policy_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, version text NOT NULL, body_sha256 text NOT NULL, effective_at timestamptz NOT NULL DEFAULT now(), counsel_reviewed boolean NOT NULL DEFAULT false, UNIQUE(kind,version));
CREATE TABLE consent_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, athlete_id uuid NOT NULL REFERENCES athletes ON DELETE CASCADE, guardian_user_id uuid NOT NULL REFERENCES users, policy_version_id uuid NOT NULL REFERENCES policy_versions, purpose text NOT NULL CHECK(purpose IN ('child_account','portrait','report_email')), granted boolean NOT NULL, ip inet, user_agent text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX consent_events_current ON consent_events(athlete_id,purpose,created_at DESC);
CREATE TABLE training_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, athlete_id uuid NOT NULL REFERENCES athletes ON DELETE CASCADE, trained_on date NOT NULL, type text NOT NULL, minutes int NOT NULL CHECK(minutes BETWEEN 1 AND 1440), intensity text NOT NULL CHECK(intensity IN ('low','mid','high')), memo text NOT NULL DEFAULT '', author_user_id uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX training_sessions_athlete_day ON training_sessions(org_id,athlete_id,trained_on DESC) INCLUDE(minutes);
CREATE TABLE game_appearances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, athlete_id uuid NOT NULL REFERENCES athletes ON DELETE CASCADE, played_on date NOT NULL, competition text NOT NULL DEFAULT '', opponent text NOT NULL DEFAULT '', result text NOT NULL DEFAULT '', score text NOT NULL DEFAULT '', performance text NOT NULL DEFAULT '', at_bats int NOT NULL DEFAULT 0 CHECK(at_bats>=0), hits int NOT NULL DEFAULT 0 CHECK(hits>=0 AND hits<=at_bats), walks int NOT NULL DEFAULT 0 CHECK(walks>=0), author_user_id uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX game_appearances_athlete_day ON game_appearances(org_id,athlete_id,played_on DESC) INCLUDE(at_bats,hits,walks);
CREATE TABLE goals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, athlete_id uuid NOT NULL REFERENCES athletes ON DELETE CASCADE, title text NOT NULL, metric text NOT NULL CHECK(metric IN ('week_training_days','month_batting_average','season_hits')), target_numeric numeric NOT NULL, due_on date, UNIQUE(athlete_id,metric));
CREATE UNIQUE INDEX goals_athlete_metric ON goals(athlete_id,metric);
CREATE TABLE coach_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, athlete_id uuid NOT NULL REFERENCES athletes ON DELETE CASCADE, author_user_id uuid NOT NULL REFERENCES users, body text NOT NULL, visible_to_guardian boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cheers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, athlete_id uuid NOT NULL REFERENCES athletes ON DELETE CASCADE, author_user_id uuid NOT NULL REFERENCES users, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE coach_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, athlete_id uuid NOT NULL REFERENCES athletes ON DELETE CASCADE, author_user_id uuid NOT NULL REFERENCES users, body text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','done')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, athlete_id uuid NOT NULL REFERENCES athletes ON DELETE CASCADE, kind text NOT NULL CHECK(kind='photo'), bucket_key text NOT NULL UNIQUE, created_by uuid NOT NULL REFERENCES users, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX media_assets_live ON media_assets(org_id,athlete_id) WHERE deleted_at IS NULL;
CREATE TABLE media_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), media_id uuid NOT NULL REFERENCES media_assets ON DELETE CASCADE, author_user_id uuid NOT NULL REFERENCES users, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE plans(code text PRIMARY KEY, interval text NOT NULL CHECK(interval IN ('month','year')), supply_krw int NOT NULL, vat_krw int NOT NULL, seat_athletes int NOT NULL, seat_coaches int NOT NULL, seat_guardians_per_athlete int NOT NULL, seat_org_admins int NOT NULL);
INSERT INTO plans VALUES('academy_monthly_v1','month',100000,10000,100,10,2,3);
CREATE TABLE subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs ON DELETE CASCADE, plan_code text NOT NULL REFERENCES plans, status text NOT NULL CHECK(status IN ('incomplete','trialing','active','past_due','canceled')), current_period_start date NOT NULL, current_period_end date NOT NULL, grace_until timestamptz, cancel_at timestamptz, read_until timestamptz, export_until timestamptz, provider text NOT NULL DEFAULT 'manual', provider_customer_ref text, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX subscriptions_one_open_org ON subscriptions(org_id) WHERE status <> 'canceled';
CREATE TABLE invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES orgs, subscription_id uuid NOT NULL REFERENCES subscriptions, period_start date NOT NULL, supply_krw int NOT NULL, vat_krw int NOT NULL, total_krw int NOT NULL, due_on date NOT NULL, status text NOT NULL CHECK(status IN ('open','paid','overdue','refunded')), evidence text, UNIQUE(subscription_id,period_start));
CREATE INDEX invoices_org_status ON invoices(org_id,status);
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices, kind text NOT NULL CHECK(kind IN ('charge','refund')), provider text NOT NULL DEFAULT 'manual', provider_payment_id text, amount_krw int NOT NULL, status text NOT NULL, refund_of_payment_id uuid REFERENCES payments, idempotency_key text NOT NULL UNIQUE, receipt_url text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tax_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL UNIQUE REFERENCES invoices, nts_approval_number text, status text NOT NULL, issued_on date);
CREATE TABLE webhook_events(provider text NOT NULL,event_id text NOT NULL,payload jsonb NOT NULL,processed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(provider,event_id));
CREATE TABLE email_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), idempotency_key text NOT NULL UNIQUE, to_email text NOT NULL, template text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', status text NOT NULL CHECK(status IN ('queued','sending','sent','retry','failed')), attempts int NOT NULL DEFAULT 0, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX email_outbox_pending ON email_outbox(created_at) WHERE status IN ('queued','retry');
CREATE TABLE password_reset_tokens(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE export_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_user_id uuid NOT NULL REFERENCES users, org_id uuid NOT NULL REFERENCES orgs, athlete_id uuid REFERENCES athletes, ticket_id uuid, status text NOT NULL CHECK(status IN ('queued','ready','expired','failed')), bucket_key text, expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE weekly_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES orgs,athlete_id uuid NOT NULL REFERENCES athletes,week_start date NOT NULL,body_json jsonb NOT NULL,UNIQUE(athlete_id,week_start));
CREATE TABLE notices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,body text NOT NULL,status text NOT NULL DEFAULT 'published',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid REFERENCES orgs,user_id uuid REFERENCES users,title text NOT NULL,body text NOT NULL,category text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id bigserial PRIMARY KEY,at timestamptz NOT NULL DEFAULT now(),actor_user_id uuid REFERENCES users,org_id uuid REFERENCES orgs,athlete_id uuid REFERENCES athletes,ticket_id uuid,action text NOT NULL,object_type text,object_id text,ip inet);
CREATE INDEX audit_events_org_time ON audit_events(org_id,at DESC);
CREATE INDEX audit_events_athlete_time ON audit_events(athlete_id,at DESC);
CREATE TABLE platform_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),maintenance boolean NOT NULL DEFAULT false,support_email text,message text);
INSERT INTO platform_settings DEFAULT VALUES;
CREATE TABLE subprocessors(name text PRIMARY KEY,purpose text NOT NULL,region text NOT NULL);
ALTER TABLE login_attempts SET (autovacuum_vacuum_scale_factor=0.05,autovacuum_analyze_scale_factor=0.02,autovacuum_vacuum_threshold=1000);
ALTER TABLE audit_events SET (autovacuum_vacuum_scale_factor=0.05,autovacuum_analyze_scale_factor=0.02);
ALTER TABLE email_outbox SET (autovacuum_vacuum_scale_factor=0.05,autovacuum_analyze_scale_factor=0.02);
CREATE OR REPLACE FUNCTION purge_expired_audit_events() RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE removed bigint; BEGIN DELETE FROM public.audit_events WHERE at < now()-interval '13 months'; GET DIAGNOSTICS removed=ROW_COUNT; RETURN removed; END $$;
REVOKE ALL ON FUNCTION purge_expired_audit_events() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION purge_expired_audit_events() TO sportsgrow_app;
